<?php $pageTitle='Chat logs';include __DIR__.'/_top.php';$rows=db()->query('SELECT cm.*,u.username FROM chat_messages cm JOIN users u ON u.id=cm.user_id ORDER BY cm.id DESC LIMIT 500');?><h1>Chatbot logs</h1><section class="card scroll"><table><tr><th>Student</th><th>Role</th><th>Message</th><th>Language</th><th>Time</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><?=e($r['username'])?></td><td><?=e($r['role'])?></td><td><?=e(mb_strimwidth($r['message'],0,180,'…'))?></td><td><?=e($r['language'])?></td><td><?=e($r['created_at'])?></td></tr><?php endwhile;?></table></section><?php include __DIR__.'/../includes/footer.php';?>
